import{_ as a,c as i,o as e,a2 as n}from"./chunks/framework.PGES7OoM.js";const k=JSON.parse('{"title":"directShield","description":"Shield wallet funds directly into the active (or selected) Curvy account.","frontmatter":{"editLink":false,"rawMarkdown":"# directShield\\n\\nShield wallet funds directly into the active (or selected) Curvy account.\\nERC-20 allowance is checked and, when necessary, an exact approval is sent for\\nthe vault before calling the aggregator. A non-zero insufficient allowance is\\nreset first for USDT-style tokens. The vault pulls directly from the wallet;\\nnative deposits attach `amount` as `msg.value`.\\n\\n## Import\\n\\n```ts\\nimport { directShield } from \\"@0xcurvy/curvy-sdk/actions\\";\\n```\\n\\n## Usage\\n\\n```ts\\nconst result = await directShield({ networkSlug, amount, token, walletClient, config });\\n```\\n\\n## Signature\\n\\n```ts\\nfunction directShield(parameters: DirectShieldParameters): Promise<DirectShieldResult>\\n```\\n\\n## Returns\\n\\n`Promise<DirectShieldResult>`\\n\\nThe action resolves or returns the value shown in the signature.\\n\\n## Parameters\\n\\n### `networkSlug`\\n\\n- **Type:** `string`\\n- **Required:** yes\\n\\nNetwork whose aggregator receives the deposit.\\n\\n```ts\\nconst result = await directShield({\\n  networkSlug, // [!code focus]\\n  amount,\\n  token,\\n  walletClient,\\n});\\n```\\n\\n### `amount`\\n\\n- **Type:** `bigint`\\n- **Required:** yes\\n\\nGross amount deposited, in token base units (fees are deducted on-chain).\\n\\n```ts\\nconst result = await directShield({\\n  networkSlug,\\n  amount, // [!code focus]\\n  token,\\n  walletClient,\\n});\\n```\\n\\n### `token`\\n\\n- **Type:** `bigint`\\n- **Required:** yes\\n\\nVault token id on the selected network.\\n\\n```ts\\nconst result = await directShield({\\n  networkSlug,\\n  amount,\\n  token, // [!code focus]\\n  walletClient,\\n});\\n```\\n\\n### `walletClient`\\n\\n- **Type:** `WalletClient`\\n- **Required:** yes\\n\\nViem wallet that owns the funds and pays gas.\\n\\n```ts\\nconst result = await directShield({\\n  networkSlug,\\n  amount,\\n  token,\\n  walletClient, // [!code focus]\\n});\\n```\\n\\n### `accountId`\\n\\n- **Type:** `string`\\n- **Required:** no\\n\\nCurvy account that receives the shielded note; defaults to the active account.\\n\\n```ts\\nconst result = await directShield({\\n  networkSlug,\\n  amount,\\n  token,\\n  walletClient,\\n  accountId, // [!code focus]\\n});\\n```\\n\\n### `contractAddress`\\n\\n- **Type:** `HexString`\\n- **Required:** no\\n\\nOverride the target aggregator; defaults to the network metadata.\\n\\n```ts\\nconst result = await directShield({\\n  networkSlug,\\n  amount,\\n  token,\\n  walletClient,\\n  contractAddress, // [!code focus]\\n});\\n```\\n\\n### `vaultContractAddress`\\n\\n- **Type:** `HexString`\\n- **Required:** no\\n\\nOverride the vault approved to pull ERC-20s; defaults to the network metadata.\\n\\n```ts\\nconst result = await directShield({\\n  networkSlug,\\n  amount,\\n  token,\\n  walletClient,\\n  vaultContractAddress, // [!code focus]\\n});\\n```\\n\\n### `config`\\n\\n- **Type:** `CurvyConfig`\\n- **Required:** no\\n\\nCurvy config to use. Defaults to the ambient config.\\n\\n```ts\\nconst result = await directShield({\\n  networkSlug,\\n  amount,\\n  token,\\n  walletClient,\\n  config, // [!code focus]\\n});\\n```\\n\\n## Errors\\n\\nErrors from config resolution and the underlying SDK operation are propagated to the caller.\\n\\n## Related\\n\\n- [Interacting with assets guide](/for-programmers/interacting-with-assets)\\n\\n## Source\\n\\n[packages/@0xcurvy/sdk/src/actions/aggregator/directShield.ts](https://github.com/0xCurvy/curvy-monorepo/blob/main/packages/@0xcurvy/sdk/src/actions/aggregator/directShield.ts)\\n","rawMarkdownPath":"/_raw/sdk/actions/aggregator/directShield.md","rawMarkdownTitle":"directShield","rawMarkdownUrl":"https://docs.curvy.box/_raw/sdk/actions/aggregator/directShield.md"},"headers":[],"params":{"sdkReferenceKind":"action","category":"aggregator","action":"directShield"},"relativePath":"sdk/actions/aggregator/directShield.md","filePath":"sdk/actions/[category]/[action].md","lastUpdated":1786448401000}'),t={name:"sdk/actions/aggregator/directShield.md"};function l(r,s,h,o,d,p){return e(),i("div",null,[...s[0]||(s[0]=[n("",50)])])}const g=a(t,[["render",l]]);export{k as __pageData,g as default};
